      "path": "package.json",
      "content": "{\n\t\"name\": \"dsh-peak-runner\",\n\t\"version\": \"0.1.0\",\n\t\"description\": \"DeepSeek 峰谷价感知的任务执行器：平价时段跑 deepseek-flash 任务批，峰价前挂定时任务推迟到下一个平价时段执行。\",\n\t\"type\": \"module\",\n\t\"license\": \"MIT\",\n\t\"main\": \"lib/index.js\",\n\t\"files\": [\n\t\t\"lib/**/*.js\",\n\t\t\"cordis.patch.yml\",\n\t\t\"README.md\",\n\t\t\"LICENSE\"\n\t],\n\t\"engines\": {\n\t\t\"node\": \">=22\"\n\t},\n\t\"scripts\": {\n\t\t\"test\": \"node --test test/*.test.mjs\"\n\t},\n\t\"peerDependencies\": {\n\t\t\"@deepseek-ai/cordis\": \"^4.0.1\",\n\t\t\"@deepseek-ai/dsh-llm\": \"^0.2.0-rc.2\",\n\t\t\"@deepseek-ai/dsh-storage-domain\": \"^0.2.0-rc.2\",\n\t\t\"@deepseek-ai/dsh-system-prompt\": \"^0.2.0-rc.2\",\n\t\t\"@deepseek-ai/dsh-tools\": \"^0.2.0-rc.2\"\n\t},\n\t\"dsh\": {\n\t\t\"bundle\": {\n\t\t\t\"patch\": \"./cordis.patch.yml\"\n\t\t},\n\t\t\"compatibility\": {\n\t\t\t\"dshReleases\": {\n\t\t\t\t\"0.2.0-rc.2\": \"compatible\"\n\t\t\t}\n\t\t}\n\t},\n\t\"publishConfig\": {\n\t\t\"access\": \"public\",\n\t\t\"registry\": \"https://registry.npmjs.org/\"\n\t},\n\t\"keywords\": [\n\t\t\"dsh\",\n\t\t\"dsh-plugin\",\n\t\t\"deepseek-harness\",\n\t\t\"deepseek\",\n\t\t\"peak-offpeak\",\n\t\t\"batch-runner\",\n\t\t\"峰谷\"\n\t],\n\t\"repository\": {\n\t\t\"type\": \"git\",\n\t\t\"url\": \"git+https://github.com/439436269-ctrl/dsh-peak-runner.git\"\n\t},\n\t\"homepage\": \"https://github.com/439436269-ctrl/dsh-peak-runner#readme\",\n\t\"bugs\": {\n\t\t\"url\": \"https://github.com/439436269-ctrl/dsh-peak-runner/issues\"\n\t}\n}\n"
